//! Support for code generated by `#[derive(Event)]` and the literal macros. Not part of the public API: it changes
//! without notice.

pub use serde;

use crate::{category, event, store};

/// A category name the derive already validated while expanding.
pub const fn category(name: &'static str) -> category::CategoryName {
    match category::CategoryName::new(name) {
        Ok(name) => name,
        // The derive rejects invalid names when it expands, so only a hand-written call can get here.
        #[allow(clippy::panic)]
        Err(_) => panic!("invalid category name"),
    }
}

/// A schema version the derive already checked is not 0 while expanding.
pub const fn schema_version(version: u16) -> event::SchemaVersion {
    match event::SchemaVersion::new(version) {
        Some(version) => version,
        // The derive rejects `version = 0` when it expands, so only a hand-written call can get here.
        #[allow(clippy::panic)]
        None => panic!("schema versions start at 1"),
    }
}

/// The check behind `Event::__CHECK`: every type name is non-empty, not a system name (`$...`) and listed
/// once. It is evaluated in a `const`, so a bad list is a compile error where a crate forces the check; a
/// `const fn` has no way to return the error instead.
#[allow(clippy::panic)]
pub const fn check_types(types: &[&str]) {
    let mut index = 0;
    while index < types.len() {
        let name = types[index].as_bytes();
        if name.is_empty() {
            panic!("Event::TYPES lists an empty type name");
        }
        if name[0] == b'$' {
            panic!("Event::TYPES lists a system type name: names starting with `$` are reserved");
        }

        let mut other = index + 1;
        while other < types.len() {
            if same_bytes(name, types[other].as_bytes()) {
                panic!("Event::TYPES lists a type name twice");
            }
            other += 1;
        }
        index += 1;
    }
}

/// Whether `name` can name a store, for `store_name!`.
pub const fn is_valid_store_name(name: &str) -> bool {
    store::validate(name).is_ok()
}

/// The store name behind `store_name!`, which checks it with [`is_valid_store_name`] first and calls this in a
/// `const` item, so an invalid name is a compile error.
pub const fn store_name(name: &'static str) -> store::StoreName {
    match store::validate(name) {
        Ok(()) => store::StoreName::from_validated(name),
        // `store_name!` evaluates this in a `const` item, so the panic is a compile error. A `const fn` cannot
        // return the `Result` instead: `StoreName` has a destructor, which `const` evaluation cannot run.
        #[allow(clippy::panic)]
        Err(_) => panic!(
            "invalid store name: it must match ^[a-z][a-z0-9_]{{0,39}}$ and not be pges, public, \
             information_schema, a reserved SQL keyword, or start with pg_"
        ),
    }
}

const fn same_bytes(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }

    let mut index = 0;
    while index < a.len() {
        if a[index] != b[index] {
            return false;
        }
        index += 1;
    }

    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builds_valid_category_names() {
        const JOBS: category::CategoryName = super::category("jobs");

        assert_eq!(JOBS.as_str(), "jobs");
    }

    #[test]
    fn checks_type_lists() {
        const CHECKED: () = check_types(&["created", "renamed", "create"]);

        let () = CHECKED;
        assert_eq!(schema_version(2).get(), 2);
    }

    #[test]
    fn builds_valid_store_names() {
        const OPS: store::StoreName = super::store_name("ops");

        assert_eq!(OPS.as_str(), "ops");
    }
}
